<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount,nextTick} from 'vue'
import {ArrowRight,AlertCircle} from '@lucide/vue'
import InfoTip from './InfoTip.vue'
import type {ProcessHistory,ProcessCoincidences,ProcessPeak} from '../process-types'
const props=defineProps<{history:ProcessHistory;window:{start_ms:number;end_ms:number};enabled:boolean}>()
const emit=defineEmits<{configure:[]}>()
const metric=ref('cpu_w'),result=ref<ProcessCoincidences|null>(null),error=ref(''),loading=ref(false),selectedId=ref<number|null>(null),table=ref<HTMLElement>()
let controller:AbortController|undefined
const selected=computed(()=>props.history.snapshots.find(s=>s.sample_id===selectedId.value)||props.history.snapshots.at(-1))
const mode=ref('applications')
const applications=computed(()=>selected.value?.context.applications||[])
const method=(name:string)=>({name_rule:'Regra de nome',parent_rule:'Vínculo com o aplicativo principal',unidentified:'Aplicativo não identificado'}[name]||'Sem identificação registrada')
const entries=computed(()=>[...(selected.value?.context.entries||[])].sort((a,b)=>(b.cpu_percent??-1)-(a.cpu_percent??-1)))
const n=(value:number,d=2)=>value.toLocaleString('pt-BR',{maximumFractionDigits:d})
const time=(ms:number)=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'America/Sao_Paulo'}).format(ms)
async function load(){controller?.abort();const current=new AbortController();controller=current;loading.value=true;error.value='';try{const query=new URLSearchParams({start_ms:String(props.window.start_ms),end_ms:String(props.window.end_ms),metric:metric.value});const response=await fetch('/api/processes/coincidences?'+query,{signal:current.signal});if(!response.ok)throw new Error('Não foi possível consultar as coincidências deste período.');result.value=await response.json()}catch(e){if(!current.signal.aborted)error.value=(e as Error).message}finally{if(!current.signal.aborted)loading.value=false}}
async function inspect(peak:ProcessPeak){if(peak.sample_id===null)return;selectedId.value=peak.sample_id;await nextTick();table.value?.focus({preventScroll:true});table.value?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
watch(()=>[props.window.start_ms,props.window.end_ms,props.history.scans,metric.value],load,{immediate:true})
onBeforeUnmount(()=>controller?.abort())
</script>
<template>
<section class="process-page" aria-labelledby="process-heading">
  <div class="section-heading"><h2 id="process-heading">Processos no período</h2><InfoTip label="Sobre a coleta por processo">CPU e RSS dos processos visíveis ao serviço. Cada varredura guarda os maiores consumidores de CPU e memória, não todos os processos. CPU é fração da capacidade total da máquina; RSS pode repetir páginas compartilhadas. Não coletamos argumentos, ambiente ou caminhos. Aplicativos são identificados por regras de nome e parentesco, sem autenticar o executável. Desconhecidos ficam separados. A soma cobre apenas os processos retidos, não o aplicativo inteiro.</InfoTip><span :class="['status-badge',enabled?'positive':'warning']">{{enabled?'Grupo ativado':'Grupo desativado'}}</span></div>
  <div v-if="error" class="banner error" role="alert"><AlertCircle :size="18"/><span>{{error}}</span></div>
  <div v-if="!history.available" class="process-empty"><h3>A coleta começa após a ativação</h3><p>Não há varreduras por processo nesta janela. Ative o grupo em Configurações e aguarde pelo menos duas coletas para calcular CPU. O histórico antigo continua sem essa informação.</p><button class="button" @click="emit('configure')">Configurar processos<ArrowRight :size="15"/></button></div>
  <template v-else>
    <div class="process-stats"><span><strong>{{history.scans}}</strong> varreduras</span><span><strong>{{history.partial_scans}}</strong> limitadas</span><span><strong>{{history.failed_scans}}</strong> falharam</span><InfoTip label="Sobre a disponibilidade dos processos">Varreduras limitadas podem atingir o teto de 50 ms/4.096 PIDs ou encontrar acesso negado. Processos curtos podem desaparecer entre coletas. A primeira leitura de cada processo tem RSS, mas precisa de outra leitura para CPU. Em períodos longos, a interface retém a varredura mais próxima do centro de cada intervalo; isso não é um inventário completo.</InfoTip></div>
    <section class="process-peaks" aria-labelledby="process-peaks-heading"><div class="section-heading"><h3 id="process-peaks-heading">Aplicativos perto dos picos</h3><label class="select-label">Comparar com<select v-model="metric" aria-label="Comparar com"><option value="cpu_w">Potência da CPU</option><option value="gpu_w">Potência da GPU</option><option value="cpu_percent">Uso da CPU</option><option value="gpu_percent">Uso da GPU</option></select></label></div><p class="muted">Coincidência de intervalos, sem atribuir causa ou energia ao aplicativo.</p><p v-if="loading" role="status" class="muted">Conferindo os intervalos…</p><template v-else-if="result"><p v-if="!result.peaks.length" class="muted">Ainda não há dados da métrica escolhida neste período.</p><article v-for="peak in result.peaks" :key="peak.index" class="process-peak"><div><strong>{{n(peak.value)}} {{result.unit}}</strong><span>{{time(peak.start_ms)}} até {{time(peak.end_ms)}}</span><p v-if="peak.matches.length"><span v-for="(match,i) in peak.matches" :key="match.alias">{{i?', ':''}}{{match.name}} ({{n(match.cpu_percent,4)}}% de CPU)</span></p><p v-else class="muted">Sem intervalo de CPU por processo compatível. Isso não prova ausência de atividade.</p></div><button v-if="peak.sample_id!==null" class="text-button" @click="inspect(peak)">Ver varredura<ArrowRight :size="14"/></button></article></template></section>
    <section class="process-observations" aria-labelledby="process-observation-heading"><div class="section-heading"><h3 id="process-observation-heading">Leituras registradas</h3><label class="select-label">Varredura<select v-model.number="selectedId" aria-label="Varredura"><option :value="null">Mais recente</option><option v-for="item in [...history.snapshots].reverse()" :key="item.sample_id" :value="item.sample_id">{{time(item.time_ms)}}</option></select></label></div><p v-if="selected" class="muted">{{time(selected.time_ms)}} · até {{selected.context.top_n}} por CPU e {{selected.context.top_n}} por RSS · {{selected.context.readable}} processos lidos · {{n(selected.context.scan_ms)}} ms.</p><div class="process-view-switch segmented" role="group" aria-label="Exibir leituras por"><button :class="{active:mode==='applications'}" :aria-pressed="mode==='applications'" @click="mode='applications'">Aplicativos</button><button :class="{active:mode==='processes'}" :aria-pressed="mode==='processes'" @click="mode='processes'">Processos técnicos</button></div>
      <p class="muted process-group-scope">Soma dos processos retidos, pode ser parte do aplicativo. Abra um grupo para conferir a identificação.</p>
      <div ref="table" tabindex="0" class="table-scroll" role="region" aria-label="Leituras de processos">
      <table v-if="mode==='applications'" class="sensor-table application-table"><caption>CPU observada: soma da porcentagem da máquina dos processos retidos. RSS pode repetir páginas compartilhadas.</caption><thead><tr><th>Aplicativo / processo</th><th>CPU observada</th><th>RSS retido</th></tr></thead><tbody><tr v-for="app in applications" :key="app.id"><td><strong>{{app.name}}</strong><small>{{app.recognized?'Identificação por regra':'Não identificado'}} · {{app.observed_processes}} {{app.observed_processes===1?'processo retido':'processos retidos'}}</small><details class="application-members"><summary>Ver processos e identificação</summary><ul><li v-for="entry in app.entries" :key="`${entry.pid}-${entry.start_ticks}`"><strong>{{entry.name}}</strong> · PID {{entry.pid}}<span>{{method(entry.application?.method||'unidentified')}}</span><span v-if="entry.ancestors?.length">Parentesco registrado: {{entry.name}} ← {{entry.ancestors.map(p=>p.name+' (PID '+p.pid+')').join(' ← ')}}</span><span>CPU: {{entry.cpu_percent===null?'Aguardando referência':n(entry.cpu_percent,4)+'%'}} · RSS: {{n(entry.rss_bytes/1024**2,1)}} MiB</span></li></ul></details></td><td>{{app.cpu_percent===null?'Aguardando referência':n(app.cpu_percent,4)+'%'}}<small v-if="app.cpu_known_processes<app.observed_processes">{{app.cpu_known_processes}} de {{app.observed_processes}} com referência</small></td><td>{{n(app.rss_bytes/1024**2,1)}} MiB</td></tr></tbody></table>
      <table v-else class="sensor-table"><caption>CPU em porcentagem da máquina; RSS em memória residente, sem descontar páginas compartilhadas.</caption><thead><tr><th>Processo</th><th>CPU</th><th>RSS</th><th>Intervalo da CPU</th></tr></thead><tbody><tr v-for="entry in entries" :key="`${entry.pid}-${entry.start_ticks}`"><td><strong>{{entry.name}}</strong><small>PID {{entry.pid}}</small></td><td>{{entry.cpu_percent===null?'Aguardando referência':n(entry.cpu_percent,4)+'%'}}</td><td>{{n(entry.rss_bytes/1024**2,1)}} MiB</td><td>{{entry.interval_start_ms===null?'Primeira leitura':time(entry.interval_start_ms)+' até '+time(entry.interval_end_ms)}}</td></tr></tbody></table></div><details v-if="selected" class="process-details"><summary>Detalhes da varredura</summary><pre>{{JSON.stringify(selected,null,2)}}</pre></details></section>
  </template>
</section>
</template>
